/// Adds every generated class to `m`.
pub(crate) fn register(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_class::<Rational>()?;
    m.add_class::<ColorInfo>()?;
    m.add_class::<ObuExtension>()?;
    m.add_class::<Obu>()?;
    m.add_class::<MispTimestamp>()?;
    m.add_class::<H264Sps>()?;
    m.add_class::<H264Pps>()?;
    m.add_class::<H264SliceHeaderLight>()?;
    m.add_class::<H264ParameterSets>()?;
    m.add_class::<H265ProfileTierLevel>()?;
    m.add_class::<H265Sps>()?;
    m.add_class::<H265Vps>()?;
    m.add_class::<H265Pps>()?;
    m.add_class::<H265SliceHeaderLight>()?;
    m.add_class::<H265ParameterSets>()?;
    m.add_class::<H266ProfileTierLevel>()?;
    m.add_class::<H266Sps>()?;
    m.add_class::<H266Vps>()?;
    m.add_class::<H266Pps>()?;
    m.add_class::<H266SliceHeaderLight>()?;
    m.add_class::<H266ParameterSets>()?;
    m.add_class::<Av1SequenceHeader>()?;
    m.add_class::<Av1FrameHeaderLight>()?;
    m.add_class::<Av1ObuStream>()?;
    m.add_class::<AdtsFrame>()?;
    m.add_class::<Mpeg2AudioFrame>()?;
    Ok(())
}
